<div class="mb-3 d-flex gap-2"><a href="<?= e(url('/users/create')) ?>" class="btn btn-primary"><i class="bi bi-person-plus"></i> Nouvel utilisateur</a><?php if (can('roles.manage')): ?><a href="<?= e(url('/roles')) ?>" class="btn btn-outline-secondary"><i class="bi bi-shield-lock"></i> Rôles & permissions</a><?php endif; ?></div>
<div class="card"><div class="table-responsive"><table class="table table-sm table-hover mb-0 align-middle"><thead><tr><th>Nom</th><th>Identifiant</th><th>Rôle</th><th>Boutique / caisse</th><th>PIN</th><th>Dernière connexion</th><th>État</th><th></th></tr></thead><tbody>
<?php foreach ($users as $x): $locked = $x['locked_until'] && strtotime($x['locked_until']) > time(); ?>
<tr class="<?= (int) $x['active'] === 1 ? '' : 'text-secondary' ?>"><td class="fw-semibold"><?= e($x['full_name']) ?></td><td><?= e($x['username']) ?></td><td><?= e($x['role']) ?></td><td><?= e($x['store'] ?? '—') ?> / <?= e($x['register'] ?? '—') ?></td><td><?= $x['pin_hash'] ? '<i class="bi bi-check-circle text-success"></i>' : '' ?><?= $x['badge_hash'] ? ' <i class="bi bi-wifi" title="Badge"></i>' : '' ?></td><td><?= e(fdate($x['last_login_at'])) ?></td>
<td><?= (int) $x['active'] === 1 ? '<span class="badge bg-success">actif</span>' : '<span class="badge bg-secondary">désactivé</span>' ?><?= $locked ? ' <span class="badge bg-danger">verrouillé</span>' : '' ?><?= (int) $x['must_change_password'] === 1 ? ' <span class="badge bg-warning text-dark">mdp à changer</span>' : '' ?></td>
<td class="text-end text-nowrap"><a href="<?= e(url('/users/' . $x['id'] . '/edit')) ?>" class="btn btn-sm btn-light"><i class="bi bi-pencil"></i></a>
<?php if ($locked || (int) $x['failed_attempts'] > 0): ?><form class="d-inline" method="post" action="<?= e(url('/users/' . $x['id'] . '/unlock')) ?>"><?= csrf_field() ?><button class="btn btn-sm btn-light" title="Déverrouiller"><i class="bi bi-unlock"></i></button></form><?php endif; ?>
<form class="d-inline" method="post" action="<?= e(url('/users/' . $x['id'] . '/toggle')) ?>" data-confirm="<?= (int) $x['active'] === 1 ? 'Désactiver' : 'Réactiver' ?> le compte de <?= e($x['full_name']) ?> ?"><?= csrf_field() ?><button class="btn btn-sm btn-light" title="<?= (int) $x['active'] === 1 ? 'Désactiver' : 'Réactiver' ?>"><i class="bi bi-<?= (int) $x['active'] === 1 ? 'person-x text-danger' : 'person-check text-success' ?>"></i></button></form></td></tr>
<?php endforeach; ?>
</tbody></table></div></div>
